// 推播名單。正式環境換成 HTTP Request 打你的後端,或 Postgres / MySQL 節點。
//
// 回傳格式：每個 item 一位收件人。

const recipients = [
  { chatId: 111111111, name: '範例使用者 A' },
  { chatId: 222222222, name: '範例使用者 B' },
];

const text = $json.text || '這是一則測試廣播。';

// 每次重跑都從乾淨的統計開始
const staticData = $getWorkflowStaticData('global');
staticData.broadcast = { sent: 0, blocked: [], retry: [], startedAt: new Date().toISOString() };

return recipients.map((r) => ({ json: { ...r, text } }));

// 把送出結果分成三類。三類的後續處理完全不同,混在一起是最常見的錯。
//
//   2xx        成功
//   403        使用者封鎖了 bot → 終局錯誤,要從名單移除,重試永遠不會成功
//   429 / 5xx  暫時性 → 照對方給的秒數等,之後重送

const staticData = $getWorkflowStaticData('global');
staticData.broadcast = staticData.broadcast || { sent: 0, blocked: [], retry: [] };

const sources = $('分批').all();
let waitSeconds = 1;   // 沒被限流時的基本節流：全域上限約 30 則/秒

$input.all().forEach((item, i) => {
  const chatId = sources[i]?.json.chatId;
  const status = item.json.statusCode ?? 0;
  const body = item.json.body ?? {};

  if (status >= 200 && status < 300) {
    staticData.broadcast.sent += 1;
    return;
  }

  if (status === 403) {
    // "bot was blocked by the user" / "bot was kicked from the group"
    staticData.broadcast.blocked.push({ chatId, reason: body.description ?? '403' });
    return;
  }

  staticData.broadcast.retry.push({ chatId, status, reason: body.description ?? '' });

  if (status === 429) {
    // ★ Telegram 直接告訴你要等幾秒。照它說的等,不要用固定間隔。
    const retryAfter = body.parameters?.retry_after ?? 30;
    waitSeconds = Math.max(waitSeconds, retryAfter);
  }
});

return [{ json: { waitSeconds, progress: staticData.broadcast.sent } }];

const s = $getWorkflowStaticData('global').broadcast ?? { sent: 0, blocked: [], retry: [] };

return [{
  json: {
    已送出: s.sent,
    已封鎖: s.blocked.length,
    待重送: s.retry.length,
    封鎖名單: s.blocked,
    重送名單: s.retry,
    提醒: '封鎖名單要寫回你的資料庫並停止推播；重送名單請在限流解除後另跑一次。',
  },
}];
